// QR checkpoint for school duty teachers. Display-only QR is generated by
// the authenticated Worker (not by a third-party QR image service).
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const state={qr:null,queue:[],date:'',now:'',refreshTimer:null,qrTimer:null,alive:false,busy:false};
export function createLateGate({api,mount,toast,safeRun}){
 function clearTimers(){
  if(state.refreshTimer)clearInterval(state.refreshTimer);
  if(state.qrTimer)clearInterval(state.qrTimer);
  state.refreshTimer=null;state.qrTimer=null;
 }
 function destroy(){state.alive=false;clearTimers();state.qr=null;state.busy=false}
 function render(){
  const pending=state.queue.filter(x=>x.state==='pending'),verified=state.queue.filter(x=>x.state==='verified');
  const statuses={pending:'รอครูเวรตรวจสอบ',verified:'ยืนยันแล้ว',rejected:'ไม่อนุมัติ'};
  mount(`<div class="stack late-qr-page">
   <header class="row between"><div><h2>📷 จุดสแกน QR ลงชื่อมาสาย</h2>
    <p class="muted">เปิด QR บนจอครูเวรให้นักเรียนสแกนด้วยกล้องโทรศัพท์ • หลัง 08.00 น. ตามเวลาไทย</p></div>
    <span class="tag">วันที่ ${esc(state.date||'-')}</span></header>
   <div class="late-qr-layout">
    <section class="card stack late-qr-station">
     <h3>QR สำหรับนักเรียน</h3>
     <p class="muted">QR มีอายุ 180 วินาที เปลี่ยนอัตโนมัติเมื่อเปิดจุดสแกน และนักเรียนต้องเข้าบัญชีของตนเองเพื่อยืนยัน</p>
     <div class="late-qr-image" id="lateQrImage">${state.qr?.svg||'<div class="empty">กดเปิดจุดสแกนเพื่อสร้าง QR</div>'}</div>
     <strong id="lateQrRemaining" role="timer" class="late-qr-time">${state.qr?'กำลังตรวจสอบเวลา':'ยังไม่เปิดจุดสแกน'}</strong>
     <div class="row"><button id="lateQrStart" class="button" type="button">${state.qr?'สร้าง QR ใหม่':'เปิดจุดสแกน QR'}</button>
      <button id="lateQrStop" class="button secondary" type="button" ${state.qr?'':'disabled'}>ปิดจุดสแกนบนจอนี้</button></div>
     <p class="muted">ห้ามถ่ายภาพ QR ส่งลงกลุ่ม นักเรียนต้องสแกน QR ล่าสุดจากจอครูเวร และรายการต้องรอครูยืนยัน</p>
    </section>
    <section class="card stack">
     <div class="row between"><h3>รายชื่อนักเรียนลงชื่อวันนี้</h3><button id="lateQrRefresh" type="button" class="button secondary">รีเฟรช</button></div>
     <div class="grid two"><div class="summary"><strong>${pending.length}</strong><p class="muted">รอยืนยัน</p></div>
      <div class="summary"><strong>${verified.length}</strong><p class="muted">ยืนยันแล้ว</p></div></div>
     <p class="muted" role="status">ข้อมูลอัปเดตอัตโนมัติประมาณทุก 6 วินาที • เวลาลงชื่อมาจากเซิร์ฟเวอร์ ไม่ใช่นาฬิกามือถือ</p>
     <div class="late-qr-list" aria-live="polite">${state.queue.length?state.queue.map(item=>`
       <article class="late-qr-entry">
        <div class="row between"><strong>${esc(item.full_name)}</strong><span class="tag">${esc(item.arrived_at)} น.</span></div>
        <p class="muted">${esc(item.student_no)} • ${esc(item.classroom_label||'ไม่พบห้องเรียน')} • เลขที่ ${esc(item.roll_no||'-')}</p>
        ${item.reason?`<p>เหตุผล: ${esc(item.reason)}</p>`:''}
        <p class="${item.state==='pending'?'warn':'muted'}">${statuses[item.state]||esc(item.state)}</p>
        ${item.state==='pending'?`<div class="row">
          <button class="button" data-qr-review="${Number(item.id)}" data-status="verified" type="button">ยืนยันมาสาย</button>
          <button class="button secondary" data-qr-review="${Number(item.id)}" data-status="rejected" type="button">ไม่อนุมัติ</button>
         </div>`:''}
       </article>`).join(''):'<p class="empty">ยังไม่มีนักเรียนลงชื่อด้วย QR ในวันนี้</p>'}</div>
    </section>
   </div></div>`);
  document.querySelector('#lateQrStart')?.addEventListener('click',()=>safeRun(rotate));
  document.querySelector('#lateQrStop')?.addEventListener('click',()=>safeRun(async()=>{
   await api('/api/late/qr/stop',{method:'POST',body:{}});
   state.qr=null;render();toast('ปิดจุดสแกนและยกเลิก QR ที่ยังไม่หมดอายุแล้ว');
  }));
  document.querySelector('#lateQrRefresh')?.addEventListener('click',()=>safeRun(()=>poll(true)));
  document.querySelectorAll('[data-qr-review]').forEach(button=>button.addEventListener('click',()=>safeRun(async()=>{
    const id=Number(button.dataset.qrReview),decision=button.dataset.status;
    if(!confirm((decision==='verified'?'ยืนยัน':'ไม่อนุมัติ')+'การลงชื่อมาสายรายการนี้?'))return;
    button.disabled=true;
    try{await api('/api/late/qr/'+id+'/review',{method:'POST',body:{state:decision}});
      toast(decision==='verified'?'ยืนยันและบันทึกมาสายสำเร็จ':'บันทึกผลไม่อนุมัติแล้ว');await poll(true);
    }finally{if(button.isConnected)button.disabled=false}
   })));
  showRemaining();
 }
 function showRemaining(){
  const el=document.querySelector('#lateQrRemaining');if(!el)return;
  if(!state.qr){el.textContent='ยังไม่เปิดจุดสแกน';return}
  const seconds=Math.max(0,Math.ceil(state.qr.expiresAt-Date.now()/1000));
  el.textContent=seconds?'QR นี้หมดอายุใน '+seconds+' วินาที':'QR หมดอายุ กำลังขอ QR ใหม่';
 }
 async function poll(renderOnChange=false){
  if(!state.alive||state.busy)return;
  state.busy=true;
  try{
   const response=await api('/api/late/qr/queue');
   if(!state.alive)return;
   const before=JSON.stringify(state.queue);
   state.queue=response.items||[];
   state.date=response.date;state.now=response.time;
   if(renderOnChange||JSON.stringify(state.queue)!==before)render();
  }finally{state.busy=false}
 }
 async function rotate(){
  if(!state.alive)return;
  const answer=await api('/api/late/qr/rotate',{method:'POST',body:{}});
  if(!state.alive)return;
  state.qr=answer;
  render();
 }
 async function load(){
  destroy();state.alive=true;state.queue=[];state.date='';render();
  await poll(true);
  state.refreshTimer=setInterval(()=>{if(state.alive)poll().catch(e=>console.warn('Late QR queue refresh failed',e?.name))},6000);
  state.qrTimer=setInterval(()=>{
   if(!state.alive)return;
   showRemaining();
   if(state.qr&&Date.now()/1000>=state.qr.expiresAt-12){
    // Only one rotation request at a time; retries on the next interval.
    const current=state.qr;state.qr=null;
    rotate().catch(e=>{state.qr=current;console.warn('Late QR rotation failed',e?.name)});
   }
  },1000);
 }
 return {load,destroy};
}
